<script lang="ts">import{onMount}from'svelte';import{get}from'svelte/store';import{connection,connectionState}from'$lib/connection';import{ApiClient,type OrchestrationView}from'$lib/api';let list=$state<OrchestrationView[]>([]),v=$state<OrchestrationView|null>(null),prompt=$state(''),err=$state(''),remote=$state(false),cost=$state(5000000),workers=$state(2),models=$state<any[]>([]),stop:AbortController|null=null,cursor=0;const api=()=>new ApiClient(get(connection));async function load(){if(get(connectionState).kind!=='connected')return;try{list=await api().listOrchestrations();models=await api().listOrchestrationModels();if(v)v=await api().getOrchestration(v.orchestration_id)}catch(e){err=String(e)}}async function open(x:OrchestrationView){v=await api().getOrchestration(x.orchestration_id);stop?.abort();stop=new AbortController();cursor=0;void api().streamOrchestrationEvents(x.orchestration_id,0,e=>{cursor=Math.max(cursor,e.id);void load()},stop.signal).catch(()=>{})}async function create(){try{v=await api().createOrchestration({prompt,data_class:'workspace',compartments:[],reasoning:'balanced',remote_allowed:remote,prefer_local:true,max_model_calls:32,max_input_tokens:250000,max_output_tokens:120000,max_remote_cost_micros:cost,max_concurrent_workers:workers,max_wall_time_millis:3600000});prompt='';await load()}catch(e){err=String(e)}}async function act(action:Record<string,unknown>){if(!v)return;v=await api().orchestrationAction(v.orchestration_id,action);await load()}onMount(()=>{void load();return()=>stop?.abort()});</script>
<div class="page"><div class="page-heading"><div><h1>Orchestrations</h1><p>Validated DAGs, model assignments, spend, artifacts and controls.</p></div><button class="secondary" onclick={load}>Refresh</button></div>{#if err}<div class="notice error">{err}</div>{/if}<section class="orch-create"><textarea bind:value={prompt} placeholder="Describe a complex task"></textarea><label><input type="checkbox" bind:checked={remote}/>remote</label><label>µ$<input type="number" min="0" bind:value={cost}/></label><label>workers<input type="number" min="1" bind:value={workers}/></label><button class="primary" disabled={!prompt.trim()} onclick={create}>Plan & run</button></section><div class="orch-layout"><aside class="orch-list">{#each list as x}<button class:active={v?.orchestration_id===x.orchestration_id} onclick={()=>open(x)}><strong>{x.orchestration_id.slice(0,8)}</strong><small>rev {x.graph_revision} · {x.tasks.length} tasks</small></button>{/each}</aside>{#if v}<section class="orch-detail"><header><code>{v.orchestration_id}</code><div class="plugin-actions"><button class="secondary" onclick={()=>act({action:'narrow',remote_allowed:false,max_remote_cost_micros:cost,max_concurrent_workers:workers})}>Narrow/local</button><button class="secondary danger" onclick={()=>act({action:'cancel'})}>Cancel</button></div></header><div class="orch-metrics"><b>{v.usage.calls} calls</b><b>{v.usage.input_tokens} in</b><b>{v.usage.output_tokens} out</b><b>{v.usage.remote_cost_micros} µ$</b></div><div class="dag-grid">{#each v.tasks as t}<article class="dag-node" data-state={t.state}><strong>{t.key}</strong><span>{t.state}</span><p>{t.description}</p>{#if t.attempts.length}<small>{t.attempts.at(-1)?.provider_id}/{t.attempts.at(-1)?.profile_id}</small>{/if}{#if t.state==='failed'||t.state==='unknown'}<div><button class="secondary" onclick={()=>act({action:'retry',task_node_id:t.id,prior_attempt_id:t.attempts.at(-1)?.attempt_id,mode:'same_worker'})}>Retry</button><button class="secondary" onclick={()=>act({action:'retry',task_node_id:t.id,prior_attempt_id:t.attempts.at(-1)?.attempt_id,mode:'reassign'})}>Reassign</button></div>{/if}<select onchange={(e)=>{const m=models.find(x=>x.profile_id===(e.currentTarget as HTMLSelectElement).value);if(m)void act({action:'pin',task_node_id:t.id,profiles:[{id:m.profile_id,revision:m.revision}]})}}><option value="">Pin model…</option>{#each models as m}<option value={m.profile_id}>{m.profile_id}</option>{/each}</select></article>{/each}</div><details><summary>Routing</summary><pre>{JSON.stringify(v.routing,null,2)}</pre></details><details><summary>Artifacts</summary><pre>{JSON.stringify(v.artifacts,null,2)}</pre></details></section>{:else}<section class="subtle-empty">Select an orchestration.</section>{/if}</div></div>
